const item = $input.first().json;

// Ensure it's an inbound message event and data exists
if (!item.data || item.event !== 'message:in:new') {
  return []; // Stop here for non-message events or receipts
}

const msg = item.data;
const contact = msg.chat && msg.chat.contact ? msg.chat.contact : {};

let text = '';
if (msg.type === 'text') {
  text = msg.body || '';
} else if (msg.type === 'interactive') {
  const i = msg.interactive || {};
  text = (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title) || '';
}

return [{ 
  json: {
    message_id: msg.id,
    phone: msg.fromNumber || msg.from,
    name: contact.name || msg.meta?.notifyName || '',
    type: msg.type,
    text: text.trim(),
    correlation_id: (msg.id ? msg.id.slice(-12) : 'msg') + '-' + Date.now(),
    received_at: msg.date || new Date().toISOString()
  }
}];

const msg = $('Normalize').first().json;
const rec = $input.first().json;
// Airtable may return the columns inside a 'fields' object; handle both shapes
const c = rec.fields || rec;
return [{ json: {
  ...msg,
  conv_id: rec.id,
  state: c.state || 'idle',
  language: c.language || '',
  human_takeover: c.human_takeover === true,
  pending_service_id: c.pending_service_id || '',
  pending_slots: c.pending_slots || '',
  pending_appointment_id: c.pending_appointment_id || ''
}}];

const c = $('Build Context').first().json;
const t = c.text.toLowerCase().trim();
let route = 'llm';
if (['human', 'humano', 'agent', 'agente', 'persona'].includes(t)) route = 'handoff';
else if (['reset', 'menu', 'menú', 'start', 'inicio', 'reinicio', 'reiniciar'].includes(t)) route = 'reset';
else if (/^[0-9]{1,2}$/.test(t) && (c.state === 'choosing_service' || c.state === 'choosing_slot')) route = 'choice';
return [{ json: { ...c, route } }];

const c = $('Quick Rules').first().json;
const raw = $input.first().json;

// Target the deep nested structure: raw.output[0].content[0].text
let text = '';
if (raw.output && Array.isArray(raw.output) && raw.output[0]) {
  const content = raw.output[0].content;
  if (content && Array.isArray(content) && content[0]) {
    text = content[0].text || '';
  }
}

// Fallbacks for safety
if (!text) {
  text = raw.text || raw.message?.content || '';
}
if (typeof text !== 'string') text = JSON.stringify(text);

// Clean up markdown block code fences if present
const fence = String.fromCharCode(96).repeat(3);
text = text.split(fence + 'json').join('').split(fence).join('').trim();

const allowed = ['faq', 'price', 'availability', 'book', 'lead_info', 'human', 'greeting', 'thanks', 'out_of_scope'];
let ai = null;
try { ai = JSON.parse(text); } catch (e) { ai = null; }
const ok = !!(ai && allowed.includes(ai.intent));

// Match against Airtable fields nested object structure
const validIds = $('Get Services').all().map(i => i.json.fields?.service_id);

const result = {
  language: ok && (ai.language === 'es' || ai.language === 'en') ? ai.language : (c.language || 'en'),
  intent: ok ? ai.intent : 'low_confidence',
  service_id: ok && validIds.includes(ai.service_id) ? ai.service_id : '',
  confidence: ok && typeof ai.confidence === 'number' ? ai.confidence : 0,
  date_hint: ok && ai.date_hint ? String(ai.date_hint) : '',
  ai_valid: ok
};

if (result.confidence < 0.6) result.intent = 'low_confidence';
return [{ json: { ...c, ...result } }];

const c = $input.first().json;

// 1. Fetch data safely from Validate AI JSON if it went through the LLM path
let aiNode = {};
try {
  aiNode = $('Validate AI JSON').item.json;
} catch (e) {
  // Bypassed the AI path (e.g., direct route text matching)
}

// 2. FETCH ORIGINAL CONTEXT VALUES (Fixes the missing state properties)
let baseContext = {};
try {
  baseContext = $('Build Context').item.json;
} catch (e) {
  baseContext = c; // Fallback to current input if Build Context is inaccessible
}

const finalIntent = aiNode.intent || c.intent || 'low_confidence';
const finalLanguage = aiNode.language || c.language || baseContext.language || 'en';
const L = finalLanguage === 'es' ? 'es' : 'en';

// Map routing behavior based on conditions
const route = c.route || baseContext.route;
const key = route === 'reset' ? 'reset' : (route === 'handoff' ? 'handoff' : finalIntent);

const T = {
  greeting: { 
    en: 'Hi! I am the virtual assistant of BrightSmile Dental. I can answer questions, check prices and book appointments. How can I help?', 
    es: '¡Hola! Soy el asistente virtual de BrightSmile Dental. Puedo responder preguntas, consultar precios y agendar citas. ¿En qué le puedo ayudar?' 
  },
  thanks: { 
    en: 'You are welcome! Let me know if you need anything else.', 
    es: '¡Con gusto! Avíseme si necesita algo más.' 
  },
  reset: { 
    en: 'Okay, we start over. How can I help you?', 
    es: 'De acuerdo, empecemos de nuevo. ¿En qué le puedo ayudar?' 
  },
  handoff: {
    en: 'I am transferring you to a human agent. Please hold.',
    es: 'Le estoy transfiriendo a un agente humano. Por favor espere.'
  },
  out_of_scope: { 
    en: 'I cannot give medical advice. The dentist can help you at your visit. I can book you an appointment, or reply HUMAN to talk to our team.', 
    es: 'No puedo dar consejos médicos. El dentista puede ayudarle en su visita. Puedo agendarle una cita, o responda HUMANO para hablar con nuestro equipo.' 
  },
  low_confidence: { 
    en: 'I am not sure I understood, and I do not want to give you wrong information. Ask me about hours, prices, insurance or booking, or reply HUMAN to talk to our team.', 
    es: 'No estoy seguro de haber entendido y no quiero darle información incorrecta. Pregúnteme por horarios, precios, seguro o citas, o responda HUMANO para hablar con nuestro equipo.' 
  }
};

const row = T[key] || T.low_confidence;
const isReset = key === 'reset';

return [{ json: { 
  ...c,
  intent: finalIntent,
  language: finalLanguage,
  reply_text: row[L], 
  tool_used: 'template:' + key,
  new_state: isReset ? 'idle' : (baseContext.state || 'idle'),
  new_pending_slots: isReset ? '' : (baseContext.pending_slots || ''),
  new_pending_service: isReset ? '' : (baseContext.pending_service_id || ''),
  new_pending_appt: isReset ? '' : (baseContext.pending_appointment_id || '') 
}}];

const c = $('Validate AI JSON').first().json;
const NL = String.fromCharCode(10);
const list = $('Get FAQ').all().map(i => {
  const f = i.json.fields || {};
  return (f.kb_id || '') + ' | ' + (f.category || '') + ' | ' + (f.question_en || '') + ' | ' + (f.question_es || '');
}).join(NL);
return [{ json: { list, text: c.text } }];

const c = $('Validate AI JSON').first().json;

// Extract rows correctly accounting for Airtable's .fields wrapper
const kb = $('Get FAQ').all().map(i => ({
  id: i.json.id,
  ...(i.json.fields || {})
}));

const raw = $input.first().json;

// Safely extract text from OpenAI response node output
let text = '';
if (raw.output && Array.isArray(raw.output) && raw.output[0]) {
  const content = raw.output[0].content;
  if (content && Array.isArray(content) && content[0]) {
    text = content[0].text || '';
  }
}
if (!text) {
  text = raw.text || raw.message?.content || raw.content || '';
}
if (typeof text !== 'string') text = JSON.stringify(text);

// Clean markdown fences
const fence = String.fromCharCode(96).repeat(3);
text = text.split(fence + 'json').join('').split(fence).join('').trim();

let m = {};
try { m = JSON.parse(text); } catch (e) { m = {}; }

const L = c.language === 'es' ? 'es' : 'en';

// Match kb_id against Airtable fields
const row = kb.find(r => r.kb_id === m.kb_id);
const keep = { 
  new_state: c.state, 
  new_pending_slots: c.pending_slots, 
  new_pending_service: c.pending_service_id, 
  new_pending_appt: c.pending_appointment_id 
};

if (row && Number(m.confidence) >= 0.7) {
  return [{ json: { 
    ...c, 
    ...keep, 
    reply_text: row['answer_' + L] || row['answer_en'] || 'Information found.', 
    tool_used: 'kb:' + row.kb_id 
  } }];
}

const miss = { 
  en: 'I do not have a confirmed answer to that, and I do not want to guess. Reply HUMAN and our team will help you.', 
  es: 'No tengo una respuesta confirmada para eso y no quiero adivinar. Responda HUMANO y nuestro equipo le ayudará.' 
};

return [{ json: { 
  ...c, 
  ...keep, 
  reply_text: miss[L], 
  tool_used: 'kb:none', 
  intent: 'faq_miss' 
} }];

const c = $('Validate AI JSON').first().json;
const L = c.language === 'es' ? 'es' : 'en';
const NL = String.fromCharCode(10);

// Correctly unwrap Airtable's .fields wrapper
const services = $('Get Services').all().map(i => ({
  id: i.json.id,
  ...(i.json.fields || {})
}));

const money = n => '$' + Number(n).toFixed(2).replace('.00', '');
const keep = { new_state: c.state, new_pending_slots: c.pending_slots, new_pending_service: c.pending_service_id, new_pending_appt: c.pending_appointment_id };
const isStale = s => { const age = (Date.now() - new Date(s.last_verified).getTime()) / 86400000; return !(age <= 90); };

const svc = services.find(s => s.service_id === c.service_id);
let text;
let tool = 'price:list';

if (svc) {
  tool = 'price:' + svc.service_id;
  if (isStale(svc)) {
    text = L === 'es' ? 'Necesito confirmar el precio actual con el equipo. Responda HUMANO y le ayudamos.' : 'I need to confirm the current price with the team. Reply HUMAN and we will help you.';
  } else if (L === 'es') {
    text = '*' + svc.name_es + '*: ' + money(svc.price_usd) + ' USD. Duración aproximada: ' + svc.duration_min + ' minutos. Un depósito de ' + money(svc.deposit_usd) + ' reserva su cita y se descuenta de su cuenta final. Los precios son estimados antes del examen y su seguro puede cambiar lo que usted paga. ¿Desea agendar?';
  } else {
    text = '*' + svc.name_en + '*: ' + money(svc.price_usd) + ' USD. Duration is about ' + svc.duration_min + ' minutes. A deposit of ' + money(svc.deposit_usd) + ' secures your booking and is deducted from your final bill. Prices are estimates before your exam, and insurance may change what you pay. Would you like to book?';
  }
} else {
  const lines = services.map(s => '- ' + s['name_' + L] + ': ' + money(s.price_usd));
  text = (L === 'es' ? 'Esta es nuestra lista de precios (USD, estimados antes del examen):' : 'Here is our price list (USD, estimates before your exam):') + NL + lines.join(NL);
}

return [{ json: { ...c, ...keep, reply_text: text, tool_used: tool } }];

const c = $input.first().json;
const services = $('Get Services').all().map(i => ({
  id: i.json.id,
  ...(i.json.fields || {})
}));
const n = parseInt(c.text, 10);
let step = 'ask_service';
let serviceId = c.service_id || '';
let chosen = null;
if (c.route === 'choice' && c.state === 'choosing_service') {
  let ids = [];
  try { ids = JSON.parse(c.pending_slots); } catch (e) { ids = []; }
  if (n >= 1 && n <= ids.length) { serviceId = ids[n - 1]; step = 'slots'; } else { step = 'invalid'; }
} else if (c.route === 'choice' && c.state === 'choosing_slot') {
  let slots = [];
  try { slots = JSON.parse(c.pending_slots); } catch (e) { slots = []; }
  serviceId = c.pending_service_id;
  if (n >= 1 && n <= slots.length) { chosen = slots[n - 1]; step = 'hold'; } else { step = 'invalid'; }
} else if (serviceId) {
  step = 'slots';
}
const svc = services.find(s => s.service_id === serviceId) || null;
return [{ json: { ...c, step, service_id: serviceId, svc, chosen_slot: chosen } }];

const c = $input.first().json;
const L = c.language === 'es' ? 'es' : 'en';
const NL = String.fromCharCode(10);

// Correctly unwrap Airtable's .fields wrapper
const services = $('Get Services').all().map(i => ({
  id: i.json.id,
  ...(i.json.fields || {})
}));

const lines = services.map((s, i) => (i + 1) + '. ' + (s['name_' + L] || s.name_en || 'Service'));
const head = L === 'es' ? '¿Qué servicio desea agendar? Responda con el número:' : 'Which service would you like to book? Reply with the number:';

return [{ json: { 
  ...c, 
  reply_text: head + NL + lines.join(NL), 
  tool_used: 'booking:ask_service',
  new_state: 'choosing_service', 
  new_pending_slots: JSON.stringify(services.map(s => s.service_id)), 
  new_pending_service: '', 
  new_pending_appt: '' 
} }];

const c = $('Booking Router').first().json;
const L = c.language === 'es' ? 'es' : 'en';
const NL = String.fromCharCode(10);
const svc = c.svc;
if (!svc) {
  const msgText = L === 'es' ? 'No pude identificar el servicio. Escriba REINICIAR y vuelva a intentar.' : 'I could not identify the service. Type RESET and try again.';
  return [{ json: { ...c, reply_text: msgText, tool_used: 'booking:no_service', slots: [], new_state: 'idle', new_pending_slots: '', new_pending_service: '', new_pending_appt: '' } }];
}
const ZONE = 'America/Chicago';
const now = DateTime.now().setZone(ZONE);
const earliest = now.plus({ hours: 4 });
const busy = [];
for (const it of $('Get Calendar Events').all()) {
  const s = it.json.start && (it.json.start.dateTime || it.json.start.date);
  const e = it.json.end && (it.json.end.dateTime || it.json.end.date);
  if (s && e) busy.push([DateTime.fromISO(s), DateTime.fromISO(e)]);
}
for (const it of $('Get Held Slots').all()) {
  const j = it.json.fields || it.json;
  if (!j.start_iso || !j.end_iso) continue;
  if (j.status === 'held' && j.hold_expires_iso && DateTime.fromISO(j.hold_expires_iso) < now) continue;
  busy.push([DateTime.fromISO(j.start_iso), DateTime.fromISO(j.end_iso)]);
}
const hours = { 1: [9, 17], 2: [9, 17], 3: [9, 17], 4: [9, 17], 5: [9, 17], 6: [9, 13] };
const slots = [];
for (let d = 0; d < 14 && slots.length < 5; d++) {
  const day = now.startOf('day').plus({ days: d });
  const h = hours[day.weekday];
  if (!h) continue;
  let t = day.set({ hour: h[0] });
  const close = day.set({ hour: h[1] });
  let perDay = 0;
  while (t.plus({ minutes: svc.duration_min }) <= close && slots.length < 5 && perDay < 2) {
    const end = t.plus({ minutes: svc.duration_min });
    const clash = busy.some(b => t < b[1] && end > b[0]);
    if (t >= earliest && !clash) { slots.push({ start: t.toISO(), end: end.toISO() }); perDay++; t = t.plus({ hours: 3 }); }
    else { t = t.plus({ minutes: 30 }); }
  }
}
const name = svc['name_' + L];
let text;
if (slots.length === 0) {
  text = L === 'es' ? 'No veo horarios disponibles en los próximos días. Responda HUMANO y nuestro equipo le ayudará.' : 'I do not see open times in the next few days. Reply HUMAN and our team will help you.';
} else {
  const lines = slots.map((s, i) => (i + 1) + '. ' + DateTime.fromISO(s.start).setZone(ZONE).setLocale(L).toFormat('ccc d LLL, h:mm a'));
  const head = L === 'es' ? 'Para *' + name + '* (unos ' + svc.duration_min + ' min) estos horarios están libres (hora del Centro). Responda con el número:' : 'For *' + name + '* (about ' + svc.duration_min + ' min) these times are open (Central Time). Reply with the number:';
  text = head + NL + lines.join(NL);
}
const has = slots.length > 0;
return [{ json: { ...c, reply_text: text, tool_used: 'booking:slots', slots,
  new_state: has ? 'choosing_slot' : 'idle', new_pending_slots: has ? JSON.stringify(slots) : '', new_pending_service: has ? c.service_id : '', new_pending_appt: '' } }];

const c = $('Booking Router').first().json;
const L = c.language === 'es' ? 'es' : 'en';
const text = L === 'es' ? 'Ese horario acaba de ocuparse. Escriba AGENDAR para ver horarios nuevos.' : 'That time was just taken. Say BOOK to see new times.';
return [{ json: { ...c, reply_text: text, tool_used: 'booking:slot_taken', new_state: 'idle', new_pending_slots: '', new_pending_service: '', new_pending_appt: '' } }];

const c = $('Booking Router').first().json;
const L = c.language === 'es' ? 'es' : 'en';

const text = L === 'es'
  ? 'Responda con uno de los números de la lista, o escriba REINICIAR para empezar de nuevo.'
  : 'Please reply with one of the numbers in the list, or say RESET to start over.';

const keep = {
  new_state: c.state,
  new_pending_slots: c.pending_slots,
  new_pending_service: c.pending_service_id,
  new_pending_appt: c.pending_appointment_id
};

return [{ json: {
  ...c,
  ...keep,
  reply_text: text,
  tool_used: 'booking:invalid_choice'
}}];

const c = $('Booking Router').first().json;
const appt = $('Create Held Appointment').first().json;
const st = $input.first().json;
const L = c.language === 'es' ? 'es' : 'en';
const NL = String.fromCharCode(10);
const when = DateTime.fromISO(c.chosen_slot.start).setZone('America/Chicago').setLocale(L).toFormat('cccc d LLLL, h:mm a');
const name = c.svc['name_' + L];
const dep = '$' + Number(c.svc.deposit_usd).toFixed(2).replace('.00', '');
const text = L === 'es'
  ? ['*Resumen de su cita*', name, when + ' (hora del Centro)', 'Depósito: ' + dep + ' (se descuenta de su cuenta final)', '', 'Pague aquí para confirmar. Su horario está reservado por 15 minutos:', st.url].join(NL)
  : ['*Your appointment summary*', name, when + ' (Central Time)', 'Deposit: ' + dep + ' (deducted from your final bill)', '', 'Pay here to confirm. Your slot is held for 15 minutes:', st.url].join(NL);
return [{ json: { ...c, reply_text: text, tool_used: 'booking:payment_link', stripe_session_id: st.id, appt_record_id: appt.id,
  new_state: 'awaiting_payment', new_pending_slots: '', new_pending_service: c.service_id, new_pending_appt: appt.id } }];

const c = $('Validate AI JSON').first().json;
const prev = $input.first().json;
const old = Number(prev.score) || 0;
const pts = { faq: 5, price: 15, availability: 20, book: 30, lead_info: 10 }[c.intent] || 0;
const bonus = c.service_id ? 10 : 0;
const score = Math.min(100, old + pts + bonus);
let status = prev.status || 'new';
if (status !== 'booked' && status !== 'handoff' && score >= 40) status = 'qualified';
return [{ json: { phone: c.phone, name: c.name, language: c.language, service_interest: c.service_id || prev.service_interest || '', score, status, last_seen: new Date().toISOString() } }];

const c = $input.first().json;
const L = c.language === 'es' ? 'es' : 'en';
const t = { en: 'Thanks, I noted that! Would you like to see our prices or book an appointment?', es: '¡Gracias, lo anoté! ¿Desea ver nuestros precios o agendar una cita?' };
return [{ json: { ...c, reply_text: t[L], tool_used: 'template:lead_info', new_state: c.state, new_pending_slots: c.pending_slots, new_pending_service: c.pending_service_id, new_pending_appt: c.pending_appointment_id } }];

const c = $('Quick Rules').first().json;
// FIX: Added .fields to properly target the Airtable object structure
const staff = $('Get Staff Number').first().json.fields.value; 
const L = c.language === 'es' ? 'es' : 'en';
const t = { 
  en: 'Okay, I am connecting you with our team. They will reply as soon as possible during business hours. Thank you for your patience.', 
  es: 'De acuerdo, le estoy conectando con nuestro equipo. Le responderán lo antes posible en horario de atención. Gracias por su paciencia.' 
};
const alert = 'Handoff requested by ' + (c.name || 'a customer') + ' (' + c.phone + '). Last message: ' + c.text + '. The bot is paused for this chat. To resume it, untick human_takeover in Airtable (Conversations).';
return [{ json: { ...c, staff_number: staff, alert_text: alert, reply_text: t[L], tool_used: 'handoff', new_state: c.state, new_pending_slots: c.pending_slots, new_pending_service: c.pending_service_id, new_pending_appt: c.pending_appointment_id } }];
